create table if not exists public.verification_checks (id uuid primary key default gen_random_uuid(), target_type text not null, target_id uuid not null, check_type text not null, status text not null default 'pending', risk_score numeric, evidence_hash text, reviewed_by uuid references public.profiles(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.safety_reports (id uuid primary key default gen_random_uuid(), reporter_id uuid references public.profiles(id) on delete set null, target_type text not null, target_id uuid not null, reason text not null, details text not null, status text not null default 'queued', priority text not null default 'normal', created_at timestamptz not null default now());
create table if not exists public.emergency_incidents (id uuid primary key default gen_random_uuid(), reporter_id uuid references public.profiles(id) on delete set null, department text not null, description text not null, latitude numeric, longitude numeric, consent_to_share_location boolean not null default false, status text not null default 'received', created_at timestamptz not null default now());
create index if not exists verification_target_idx on public.verification_checks(target_type, target_id, status); create index if not exists reports_queue_idx on public.safety_reports(status, priority, created_at); create index if not exists incidents_status_idx on public.emergency_incidents(status, created_at);
alter table public.verification_checks enable row level security; alter table public.safety_reports enable row level security; alter table public.emergency_incidents enable row level security;
